function readQueryEntries(input) {
  if (typeof input !== 'string') return input.map(([k, v]) => [decodeURIComponent(k), decodeURIComponent(v)]);
  return input.replace(/^\?/, '').split('&').filter(Boolean).map(part => {
    const i = part.indexOf('=');
    return [decodeURIComponent(i < 0 ? part : part.slice(0, i)), decodeURIComponent(i < 0 ? '' : part.slice(i + 1))];
  });
}
module.exports = { readQueryEntries };

