const test = require('node:test');
const assert = require('node:assert/strict');
const { readQueryEntries } = require('../src/query-entry.cjs');

test("string input decodes form characters once", () => {
  assert.deepEqual(readQueryEntries('?name=white+pine&mark=%2B&raw=%252B'), [['name', 'white pine'], ['mark', '+'], ['raw', '%2B']]);
  assert.deepEqual(readQueryEntries('q=blue%20sky&q=green+hill'), [['q', 'blue sky'], ['q', 'green hill']]);
});

test("pair input keeps plus and percent text literally", () => {
  const pairs = [['name', 'white+pine'], ['raw', '%2B'], ['name', 'second']];
  const before = pairs.map(pair => pair.slice());
  assert.deepEqual(readQueryEntries(pairs), before);
  assert.deepEqual(pairs, before);
  assert.deepEqual(readQueryEntries(''), []);
});

